3	import { useState, useEffect } from 'react'
4	
5	interface LoadingTimeoutResult {
6	  showConnectionHint: boolean
7	  showSlowHint: boolean
8	}
9	
10	export function useLoadingTimeout(isLoading: boolean): LoadingTimeoutResult {
11	  const [showConnectionHint, setShowConnectionHint] = useState(false)
12	  const [showSlowHint, setShowSlowHint] = useState(false)
13	
14	  useEffect(() => {
15	    if (!isLoading) {
16	      setShowConnectionHint(false)
17	      setShowSlowHint(false)
18	      return
19	    }
20	
21	    const t1 = setTimeout(() => setShowConnectionHint(true), 3000)
22	    const t2 = setTimeout(() => setShowSlowHint(true), 10000)
23	
24	    return () => {
25	      clearTimeout(t1)
26	      clearTimeout(t2)
27	    }
28	  }, [isLoading])
29	
30	  return { showConnectionHint, showSlowHint }
31	}
